def print_message(arg):
    print(arg)

def print_joints(joints, is_moving=False):
  if is_moving:
      print("JNTS_MOVING " + " ".join(format(x, ".3f") for x in joints))
  else:
      print("JNTS " + " ".join(format(x, ".6f") for x in joints))
  sys.stdout.flush()

