        # self.TIMEOUT = 10 # seconds

        # destructor

    def __del__(self):
        self.disconnect()

    # Disconnect from robot
    def disconnect(self):
        self.CONNECTED = False
        if self.eva:
            try:
                self.eva.unlock()
                self.eva = None
            except Exception as e:
                return False
        return True

    # Connect to robot
    def connect(self, ip, api_token, port=-1):
        global ROBOT_MOVING
        self.disconnect()
        print_message('Connecting to robot %s using API Token: %s' % (ip, api_token))
        # Create new socket connection
        UpdateStatus(ROBOTCOM_WORKING)
        try:
            # self.eva = Eva(ip, port)
            self.eva = Eva(ip, api_token)
            with self.eva.lock():
                self.eva.control_wait_for_ready()
                # self.eva.control_reset_errors()
        except Exception as e:
            print_message(str(e))
            return False

        with self.eva.lock():
            # version = self.eva.versions()[0]
            robotName = self.eva.name()
        # print_message("API Version:" + str(version))
        print_message("Robot Name:" + str(robotName))

        self.CONNECTED = True
        ROBOT_MOVING = False

        sys.stdout.flush()
        return True

    def recv_acknowledge(self):
        import time
        with self.eva.lock():
            #loop structure taken from lower level api because the functionality needed is not exposed
            while True:
                robot_state = self.eva.data_snapshot()['control']['state']

                if robot_state == 'error':
                    print_message('Error moving robot')
                    return False
                elif robot_state == 'ready':
                    break
                curJoints = self.eva.data_servo_positions()
                jointList = [j*180/pi for j in curJoints]
                print_joints(curJoints,True)
                time.sleep(0.1)
        return True

    def MoveJ(self,joints):
        jointList = [j*pi/180 for j in joints[:self.nDOFs]]
        try:
            with self.eva.lock():
                self.eva.control_go_to(jointList, max_speed = self.LINEARSPEED/1000.0, mode = 'automatic')
        except Exception as e:
            print_message(str(e))
            return False
        return True

